add_filter( 'woocommerce_general_settings', 'perfectpixel_second_store_address_settings' );
add_shortcode( 'store_second_address', 'perfectpixel_second_store_address_shortcode' );

function perfectpixel_second_store_address_settings( $settings ) {
	$fields = array(
		array( 'title' => '{{second_address_title}}', 'type' => 'title', 'id' => 'perfectpixel_second_address' ),
		array( 'title' => 'Διεύθυνση', 'id' => 'perfectpixel_second_address_1', 'type' => 'text', 'default' => '' ),
		array( 'title' => 'Πόλη', 'id' => 'perfectpixel_second_address_city', 'type' => 'text', 'default' => '' ),
		array( 'title' => 'Ταχυδρομικός κώδικας', 'id' => 'perfectpixel_second_address_postcode', 'type' => 'text', 'default' => '' ),
		array( 'title' => 'Τηλέφωνο', 'id' => 'perfectpixel_second_address_phone', 'type' => 'text', 'default' => '' ),
		array( 'type' => 'sectionend', 'id' => 'perfectpixel_second_address' ),
	);
	// Insert right after the "Store Address" section.
	$new = array();
	foreach ( $settings as $setting ) {
		$new[] = $setting;
		if ( isset( $setting['type'], $setting['id'] ) && 'sectionend' === $setting['type'] && 'store_address' === $setting['id'] ) {
			$new = array_merge( $new, $fields );
		}
	}
	return count( $new ) > count( $settings ) ? $new : array_merge( $settings, $fields );
}

function perfectpixel_second_store_address_shortcode() {
	$line  = trim( get_option( 'perfectpixel_second_address_1', '' ) );
	$city  = trim( get_option( 'perfectpixel_second_address_postcode', '' ) . ' ' . get_option( 'perfectpixel_second_address_city', '' ) );
	$phone = trim( get_option( 'perfectpixel_second_address_phone', '' ) );
	$parts = array_filter( array( $line, $city, $phone ) );
	return $parts ? '<address class="perfectpixel-second-address">' . implode( '<br>', array_map( 'esc_html', $parts ) ) . '</address>' : '';
}
